import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Plan 0028 — the course as a curriculum (clarity, coverage, mastery)","description":"","frontmatter":{"title":"Plan 0028 — the course as a curriculum (clarity, coverage, mastery)","type":"plan","date":"2026-10-14T00:00:00.000Z","status_note":"All three steps landed on `main` (`docs/tutorials/course/` only —\\n`toy/` at the time):\\n\\n1. **Engine + shell** (`4cf9b8c`, salvaged from the OOM reboot):\\n   `concepts.ts` (concept graph), `points.ts`, `mastery.ts`, `badges.ts`,\\n   `review.ts` + shell chrome (XP/rank, mastery meter, badges, recap).\\n2. **Per-level template + forward-ref fixes** (`ace7270`, `c23fe72`,\\n   `97ff8f4`): all 22 levels carry `why`/`terms`/`outcome`/`repo`/\\n   `module` + multi-part checkpoints; **forward references 22 → 0**\\n   (8 promoted to their teaching level, 14 incidental mentions\\n   removed; `FORWARD_REF_CEILING = 0` test); glossary panel (60\\n   concepts); prerequisite display; multi-part checkpoints feed points\\n   and per-concept mastery.\\n3. **Coverage + modules + completion** (`27fc034`, `13979cf`): six new\\n   levels (22 → 28) — `corpus`, `models`, `artifacts`, `cellstore`,\\n   `game`, `gates`; six modules with reviews that recombine concepts\\n   across ≥2 levels of their arc (tested); module completion gated on\\n   the review; `Course.completion` reports XP + rank, levels/reviews\\n   cleared, concepts mastered, badges, and the gaps the learner is\\n   equipped to attack.  `STORAGE_KEY` → `v5`.\\n\\nMeasured: **forward refs 0** (28 levels, 80 concepts); tests\\n**174 → 215** (engine 143, app 72); `vp check` / `vp run -r test` /\\n`vp run -r build` all pass."},"headers":[],"relativePath":"graphopt/project/plans/0028-course-curriculum.md","filePath":"vendored/graphopt/project/plans/0028-course-curriculum.md"}'),a={name:`graphopt/project/plans/0028-course-curriculum.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="plan-0028-—-the-course-as-a-curriculum-clarity-coverage-mastery" tabindex="-1">Plan 0028 — the course as a curriculum (clarity, coverage, mastery) <a class="header-anchor" href="#plan-0028-—-the-course-as-a-curriculum-clarity-coverage-mastery" aria-label="Permalink to “Plan 0028 — the course as a curriculum (clarity, coverage, mastery)”">​</a></h1><p>Depends on: plans 0026/0027 (the toy course&#39;s cycles 3–4), the real project&#39;s docs (<code>docs/</code>, <code>project/adrs/</code>, <code>project/retros/</code>), ADR 0002/0003/0005/0006/0007/0008.</p><h2 id="motivation-—-audited-gaps" tabindex="-1">Motivation — audited gaps <a class="header-anchor" href="#motivation-—-audited-gaps" aria-label="Permalink to “Motivation — audited gaps”">​</a></h2><p>The course is now 22 gated levels with live interactives. Audited against the goal <em>&quot;full comprehension of the project, built progressively&quot;</em>, four structural gaps stand out:</p><ol><li><strong>No prerequisite structure.</strong> Levels are a flat list. A learner cannot see what depends on what, and cannot tell whether they are ready for a level. (Forward references exist: <code>closure</code> at 2, <code>monoid/comonoid</code> at 3, <code>non-dominated set</code> at 5, <code>critical pair</code> at 11, <code>monoidal product</code> at 15 — each used before it is defined.)</li><li><strong>No per-level outcomes or terms.</strong> Each level has an <code>objective</code> one-liner but not: <em>&quot;by the end you can …&quot;</em>, the <strong>new terms</strong> it introduces, or where the idea lives in the <strong>real repo</strong> (the whole point is to improve the project).</li><li><strong>Coverage holes.</strong> Missing as lessons: the corpus/intake (166 workloads), the bench harness + ledger + gate + pinned baselines, the cost-model <em>family</em> (roofline/executor/delivered + profiles), delivery artifacts (export formats, CUDA-graph runner, the native engine), the cell store / handl bridge, the game layer (boards, players, learned priors, meta-arena), the failure taxonomy, and the engineering ratchets (coverage/ty/radon gates — how the project keeps itself honest).</li><li><strong>Gamification is thin.</strong> Gating + a % meter + a cleared badge. No points, no mastery per concept, no review, no module-level checkpoints, no completion that <em>means</em> comprehension.</li></ol><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><h3 id="a-structure-modules-prerequisites-and-outcomes" tabindex="-1">A. Structure: modules, prerequisites, and outcomes <a class="header-anchor" href="#a-structure-modules-prerequisites-and-outcomes" aria-label="Permalink to “A. Structure: modules, prerequisites, and outcomes”">​</a></h3><ul><li><p><strong>Six modules (arcs)</strong>, each 4–6 levels, each ending in a <strong>module review</strong> (spaced retrieval over that module&#39;s concepts):</p><table tabindex="0"><thead><tr><th>module</th><th>arc</th><th>levels (existing + new)</th></tr></thead><tbody><tr><td>I · Foundations</td><td>what a program is, what equality means</td><td>0 tree, 1 equal, <strong>NEW: the corpus</strong> (where programs come from), 2 reach, 3 structure</td></tr><tr><td>II · Correctness &amp; choice</td><td>certificates, frontiers, search</td><td>4 referee, 5 choice, 6 searching, 7 learning</td></tr><tr><td>III · Evaluation &amp; execution</td><td>what looks good vs what ran</td><td>8 measuring, <strong>NEW: the cost-model family</strong>, <strong>NEW: delivery artifacts</strong>, 9 architecture</td></tr><tr><td>IV · Discovery &amp; minting</td><td>growing the vocabulary</td><td>10 tensions, 11 coherence, 12 mint, 13 truthpay, 14 exposure</td></tr><tr><td>V · Substrate &amp; backends</td><td>the presentation and the ports</td><td>15 substrate, 16 ports, <strong>NEW: the cell store</strong>, <strong>NEW: the game layer</strong></td></tr><tr><td>VI · Engineering &amp; payoff</td><td>how the project stays honest, and where to help</td><td><strong>NEW: the gates</strong> (ratchets/coverage/bench), 17 negatives, 18 bounded, 19 deliver, 20 pricing, 21 improve</td></tr></tbody></table></li><li><p><strong>Every level gains four fields</strong>: <code>outcome</code> (&quot;by the end you can …&quot;), <code>terms</code> (new vocabulary, defined in-level), <code>repo</code> (the real files/paths that implement it), <code>module</code> (which arc).</p></li><li><p><strong>A concept graph</strong> (<code>concepts.ts</code>): every concept id, its label, which level introduces it, which levels use it — driving both the prerequisite display and the mastery meter.</p></li></ul><h3 id="b-per-level-template-the-clarity-contract" tabindex="-1">B. Per-level template (the clarity contract) <a class="header-anchor" href="#b-per-level-template-the-clarity-contract" aria-label="Permalink to “B. Per-level template (the clarity contract)”">​</a></h3><ol><li><strong>Why you are here</strong> — one sentence tying it to the previous level.</li><li><strong>New terms</strong> — defined <em>before</em> first use, listed and highlighted.</li><li><strong>The idea</strong> — short prose, one idea.</li><li><strong>See it</strong> — the worked example (numbers on screen).</li><li><strong>Do it</strong> — the interactive (live wherever TS can compute it).</li><li><strong>Check it</strong> — a <strong>multi-part</strong> checkpoint (≥2 questions, one of which must be answered from the interactive).</li><li><strong>You can now</strong> — the outcome restated as a capability.</li><li><strong>In the real project</strong> — file pointers + the retro/ADR.</li></ol><h3 id="c-gamification-points-mastery-review-badges" tabindex="-1">C. Gamification (points, mastery, review, badges) <a class="header-anchor" href="#c-gamification-points-mastery-review-badges" aria-label="Permalink to “C. Gamification (points, mastery, review, badges)”">​</a></h3><ul><li><strong>Points</strong>: each level awards XP — a base for passing the checkpoint plus a bonus for interacting with the live widget (so points reward <em>doing</em>, not clicking next). Module reviews award more.</li><li><strong>Mastery per concept</strong>: each concept accumulates correct answers across checkpoints <em>and</em> reviews (spaced retrieval) → a per-concept meter (weak / familiar / mastered) shown on the concept graph.</li><li><strong>Badges</strong>: e.g. <em>First Certificate</em>, <em>Sweep Breaker</em> (level 13), <em>Module I–VI Complete</em>, <em>Negative Results Kept</em> (level 17), <em>Full Comprehension</em> (all levels + all reviews ≥ threshold).</li><li><strong>Module bosses</strong>: the module review is a gated multi-question round; failing sends you back to the levels whose concepts were weak (using the mastery data) — progressive, not punitive.</li><li><strong>Completion that means something</strong>: the final state lists the concepts mastered, the levels cleared, and the gaps <em>you</em> are now equipped to attack (from level 21).</li></ul><h3 id="d-coverage-the-new-levels-six" tabindex="-1">D. Coverage: the new levels (six) <a class="header-anchor" href="#d-coverage-the-new-levels-six" aria-label="Permalink to “D. Coverage: the new levels (six)”">​</a></h3><ol><li><strong>the corpus</strong> — where programs come from: export, the intake (166 workloads, 114 verified), the three lowering bugs it caught.</li><li><strong>the cost-model family</strong> — features → roofline/executor/delivered → profiles/calibration; why one model is not enough.</li><li><strong>delivery artifacts</strong> — what &quot;runnable&quot; means: module/safetensors/ torchscript/.pt2, the CUDA-graph runner, the native Rust engine.</li><li><strong>the cell store</strong> — one record per vocabulary item (op/law/object/ handle), fragments, provenance origins, the handl bridge.</li><li><strong>the game layer</strong> — boards, players, learned priors, the meta-arena, <code>play --domain</code>; what the priors actually buy.</li><li><strong>the gates</strong> — how the project stays honest: coverage floors, ty/ruff/vulture/import-linter, the radon ratchet, bench gate + pinned baselines, and the no-new-suppressions rule.</li></ol><h2 id="constraints" tabindex="-1">Constraints <a class="header-anchor" href="#constraints" aria-label="Permalink to “Constraints”">​</a></h2><ul><li><strong>No forward references.</strong> A term used in level N must be defined in level ≤ N; a test asserts it (grep the level text against the concept graph&#39;s introduction order).</li><li>One idea per level still holds; comprehensiveness comes from <em>more levels</em>, not longer ones.</li><li>Live wherever TS can compute; illustrative numbers labelled and sourced from <code>project/retros/</code>.</li><li><code>vp check</code> / <code>vp run -r test</code> / <code>vp run -r build</code> must pass; <code>STORAGE_KEY</code> → <code>v4</code> (shape changes); progress migrates or resets cleanly (a reset is acceptable if announced).</li><li>Tests: prerequisite-order test, points/mastery unit tests, module gating test, and the existing gating/checkpoint tests updated.</li></ul><h2 id="falsification" tabindex="-1">Falsification <a class="header-anchor" href="#falsification" aria-label="Permalink to “Falsification”">​</a></h2><ul><li>If a learner can reach the end without the mastery meter leaving &quot;weak&quot; on any concept, the checkpoints are too shallow — deepen them rather than add levels.</li><li>If the concept graph cannot be built without hand-labelling every level&#39;s terms, the labels are the deliverable (keep them in data).</li><li>If the module reviews merely repeat the level checkpoints, they are not reviews — they must <em>recombine</em> concepts across the arc.</li></ul><h2 id="order" tabindex="-1">Order <a class="header-anchor" href="#order" aria-label="Permalink to “Order”">​</a></h2><ol><li><strong>C + A-skeleton</strong> (gamification engine: <code>points.ts</code>, <code>mastery.ts</code>, <code>concepts.ts</code>, badges, review round) over the existing 22 levels — self-contained, no content rewrite.</li><li><strong>B</strong> (the per-level template fields + glossary + repo pointers) applied to the existing 22 levels.</li><li><strong>D</strong> (the six new levels) + module boundaries + reviews.</li><li>Final: completion state + README/docs refresh.</li></ol>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};